/* =====================================================================
   CONFIGURACIÓN — lo único que normalmente hay que tocar
   ===================================================================== */
const CONFIG = {
  // Opcional: URL que recibe cada inscripción en JSON (Power Automate, Google Apps Script,
  // un webhook de HubSpot o un servicio interno). Vacío = nada sale del navegador.
  ENDPOINT_URL: '/api/inscripcion',
  // Edades de ingreso según Anexo No. 1 (Portafolio)
  EDAD: { titularMin: 18, titularMax: 74, polizaMax: 70, hijoMinMeses: 6, hijoMax: 24, adicionalMin: 18, adicionalMax: 74 },
  MAX_HIJOS: 4, MAX_ADICIONALES: 2, MAX_BENEFICIARIOS: 3,
  MAX_MASCOTAS: 20  // cada mascota es una asistencia independiente; el límite solo evita errores de digitación
};
const FAM = 'Titular, cónyuge e hijos';
const FAMAD = 'Titular, cónyuge, hijos + hasta 2 adicionales';

// Modalidad de contratación. min/max = número de asistencias que se pueden marcar.
// niveles = qué niveles de asistencia habilita cada plan. Hogar y Mascotas se habilitan siempre.
const MODALIDADES = [
  { v:'Tradicional', n:'Plan Tradicional', d:'Marque 2 asistencias', cubre:'Asistencias Básicas + hogar y mascota',
    min:2, max:4, niveles:['Basico'] },
  { v:'Familiar', n:'Plan Familiar', d:'Marque 3 asistencias o más', cubre:'Asistencias Light + hogar y mascota',
    min:3, max:4, niveles:['Light'], pol:1 },
  { v:'Integral', n:'Plan Integral', d:'Marque 3 asistencias o más', cubre:'Asistencias Premium + hogar y mascota',
    min:3, max:4, niveles:['Premium','PremiumAdicionales'], pol:1 },
  { v:'Individual', n:'Asistencias individuales', d:'Marque las que quiera', cubre:'Según cada asistencia', min:1, max:4 }
];
// Asistencias. fam = cubre cónyuge/hijos, adic = admite 2 adicionales, pol = incluye póliza.
const CATALOGO = [
  { g:'doctor', t:'Asistencia Doctor 360', corto:'Doctor 360', edadMax:true, o:[
    { v:'Basico', n:'Básico', cubre:'Titular' },
    { v:'Light', n:'Light', cubre:FAM, fam:1 },
    { v:'Premium', n:'Premium', d:'Incluye póliza de accidentes personales', cubre:FAM, fam:1, pol:1 },
    { v:'PremiumAdicionales', n:'Premium + adicionales', d:'Incluye póliza de accidentes personales', cubre:FAMAD, fam:1, adic:1, pol:1 } ]},
  { g:'odontologica', t:'Asistencia Odontológica 360', corto:'Odontológica 360', edadMax:true, o:[
    { v:'Basico', n:'Básico', cubre:'Titular' },
    { v:'Light', n:'Light', cubre:'Titular' },
    { v:'Premium', n:'Premium', d:'Incluye póliza de accidentes personales', cubre:FAM, fam:1, pol:1 },
    { v:'PremiumAdicionales', n:'Premium + adicionales', d:'Incluye póliza de vida', cubre:FAMAD, fam:1, adic:1, pol:1 } ]},
  { g:'funeral', t:'Asistencia Funeral 360', corto:'Funeral 360', edadMax:true, o:[
    { v:'Basico', n:'Básico', cubre:'Titular' },
    { v:'Light', n:'Light', d:'Incluye póliza de accidentes', cubre:FAM, fam:1, pol:1 },
    { v:'Premium', n:'Premium', d:'Incluye póliza de vida', cubre:FAM, fam:1, pol:1 },
    { v:'PremiumAdicionales', n:'Premium + adicionales', d:'Incluye póliza de vida', cubre:FAMAD, fam:1, adic:1, pol:1 } ]},
  { g:'hogar', t:'Asistencia Protección Hogar y Mascotas', corto:'Protección Hogar', hogar:true, o:[
    { v:'Plan1', n:'Protección Hogar Plan 1', cubre:'Servicios en la vivienda del titular' },
    { v:'Plan2', n:'Protección Hogar Plan 2', cubre:'Servicios en la vivienda del titular' },
    { v:'Plan3', n:'Protección Hogar Plan 3', cubre:'Titular del servicio + 1 dispositivo' },
    { v:'Mascotas', n:'Hogar Mascotas', cubre:'1 mascota (perro o gato) de 3 meses a 10 años y 364 días', mascota:1 },
    { v:'MascotasPlena', n:'Hogar Mascota Plena', cubre:'1 mascota + servicios en la vivienda del titular', mascota:1 } ]}
];
const PARENTESCOS = ['Padres','Padrastros/Madrastras','Nietos','Hermanos','Tíos','Tías','Primos','Sobrinos','Yernos','Nueras','Abuelos','Cuñados','Suegros'];
const PAGO = { Nomina:'El colaborador paga por nómina', Empresa:'La empresa paga', Cofinanciado:'Cofinanciado (parte por nómina)' };
const TXT_DATOS = 'Autorizo a la entidad administradora del convenio y a las compañías aliadas que prestan las asistencias y emiten las pólizas a tratar mis datos personales y los de las personas que inscribo en este formulario, incluidos los de menores de edad de quienes soy representante, para afiliarnos, prestar los servicios y gestionar el cobro, conforme a la Ley 1581 de 2012 y a la Política de Tratamiento de Datos de dicha entidad. Declaro que cuento con la autorización de las demás personas mayores de edad que inscribo.';
// Autorización expresa de descuento por nómina (modelo 1 y cofinanciado).
const txtDescuento = () => `Autorizo a ${esc(S.convenio.empresa || 'la empresa')} a descontar cada mes de mi nómina <strong id="autDescValor">${esc(pesos(valores().descuento) || '$0')}</strong>, valor de las asistencias elegidas en este formulario, mientras estén vigentes.`;
const TXT_DECL = 'Declaro haber leído, comprendido y aceptado lo indicado en este formulario, y en señal de aceptación firmo el presente documento.';
const FIRMA_BOX = {"page": 2, "x": 42, "y": 158.09, "w": 278, "h": 47};
const TEMPLATE_B64 = '';

/* =====================================================================
   ESTADO
   ===================================================================== */
const STEPS = [
  { id:'convenio', t:'Convenio' }, { id:'plan', t:'Plan' }, { id:'titular', t:'Titular' },
  { id:'familia', t:'Familia y mascota' }, { id:'beneficiarios', t:'Beneficiarios' },
  { id:'pago', t:'Pago y firma' }, { id:'revision', t:'Revisión' }
];
function nuevoEstado(convenio){
  return { convenio: convenio || { empresa_id:null, empresa:'', nit:'', asesor:'', pago:'', valorEmpresa:'', valorColaborador:'', modelo_aplicado:'' },
    modalidad:'', planes:{ mascotas:[] }, titular:{ tipodoc:'CC' }, pagadorMismo:true, pagador:{},
    mascotas:[],
    conyuge:null, hijos:[], adicionales:[], beneficiarios:[],
    pago:{ valor:'' }, aut:{ datos:false, declaracion:false, descuento:false },
    firmaModo:'pantalla', firma:null, firmaRaw:null, observaciones:'' };
}
let S = nuevoEstado();
let cur = 0, maxVisto = 0, generado = null;
const registros = []; let exportado = true;

/* =====================================================================
   UTILIDADES
   ===================================================================== */
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getP(path){ return path.split('.').reduce((o,k)=> o==null ? undefined : o[k], S); }
function setP(path, val){ const ks = path.split('.'); let o = S; ks.slice(0,-1).forEach(k=>{ if(o[k]==null) o[k]={}; o=o[k]; }); o[ks.at(-1)] = val; }
function parseFecha(s){
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s||''); if(!m) return null;
  const d = new Date(+m[3], +m[2]-1, +m[1]);
  if(d.getFullYear()!=+m[3] || d.getMonth()!=+m[2]-1 || d.getDate()!=+m[1]) return null;
  return d;
}
function edad(d, ref=new Date()){ let a = ref.getFullYear()-d.getFullYear(); const mm = ref.getMonth()-d.getMonth(); if(mm<0 || (mm===0 && ref.getDate()<d.getDate())) a--; return a; }
function meses(d, ref=new Date()){ let m = (ref.getFullYear()-d.getFullYear())*12 + ref.getMonth()-d.getMonth(); if(ref.getDate()<d.getDate()) m--; return m; }
function hoy(){ const d=new Date(); return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(); }
function maskFecha(v){ const d=v.replace(/\D/g,'').slice(0,8); return d.length>4 ? d.slice(0,2)+'/'+d.slice(2,4)+'/'+d.slice(4) : d.length>2 ? d.slice(0,2)+'/'+d.slice(2) : d; }
function pesos(v){ const n = parseInt(String(v).replace(/\D/g,''),10); return isNaN(n) ? '' : '$' + n.toLocaleString('es-CO'); }
function toast(msg){ const t=$('#toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove('show'), 3600); }
function nombreCompleto(p){ if(!p) return ''; if(p.nombre) return p.nombre; return [p.nombres, p.apellidos || [p.apellido1,p.apellido2].filter(Boolean).join(' ')].filter(Boolean).join(' '); }
const modActual = () => MODALIDADES.find(m=>m.v===S.modalidad);

/* Sesión: la empresa sale del usuario que ingresó; el equipo interno la elige de una lista. */
let SESION = null;
function empresaActual(){
  if(!SESION) return null;
  return SESION.empresa || (SESION.empresas||[]).find(e=>e.id===S.convenio.empresa_id) || null;
}
// Modelo 1: solo nómina. Modelo 2: la empresa paga o cofinancia. Modelo 3: Mixto (depende de modelo_aplicado).
function pagosPermitidos(){ 
  const e = empresaActual(); if(!e) return []; 
  const m = e.modelo === 3 ? Number(S.convenio.modelo_aplicado) : e.modelo; 
  if (!m) return [];
  return m === 2 ? ['Empresa','Cofinanciado'] : ['Nomina']; 
}
function productoHabilitado(gr, o){ const e = empresaActual(); return !e || !e.productos || !e.productos.length || e.productos.includes(gr.g+':'+o.v); }
function aplicarEmpresa(id){
  const e = SESION.empresa || (SESION.empresas||[]).find(x=>x.id===id);
  Object.assign(S.convenio, e ? { empresa_id:e.id, empresa:e.nombre, nit:e.nit } : { empresa_id:null, empresa:'', nit:'' });
  if (!e || e.modelo !== 3) S.convenio.modelo_aplicado = '';
  const p = pagosPermitidos();
  if(!p.includes(S.convenio.pago)) S.convenio.pago = p.length===1 ? p[0] : '';
}

const gr_hogar = () => CATALOGO.find(g=>g.hogar);
function cobertura(){
  const m = modActual();
  // fam y adic salen exclusivamente de las asistencias elegidas; pol puede venir además de la modalidad.
  const c = { mod:m, fam:false, adic:false, pol:!!(m&&m.pol), hogar:false, mascota:false,
              edadMax:false, n:0, sel:[], niveles:[] };
  CATALOGO.forEach(gr => {
    const elegidas = [];
    const v = S.planes[gr.g]; if(v){ const o = gr.o.find(x=>x.v===v && !x.mascota); if(o) elegidas.push(o); }
    if(gr.hogar) (S.planes.mascotas||[]).forEach(pv => { const o = gr.o.find(x=>x.v===pv && x.mascota); if(o) elegidas.push(o); });
    if(!elegidas.length) return;
    c.n++;   // la categoría cuenta una vez para las reglas del plan
    elegidas.forEach(o => {
      c.sel.push(o.n.startsWith(gr.corto) || o.n.startsWith('Hogar') ? o.n : gr.corto + ' ' + o.n); c.niveles.push({ gr, o });
      if(o.fam) c.fam = true; if(o.adic) c.adic = true; if(o.pol) c.pol = true;
      if(o.mascota) c.mascota = true;
      if(gr.hogar && !o.mascota) c.hogar = true;
      if(o.v === 'MascotasPlena') c.hogar = true;
      if(gr.edadMax) c.edadMax = true;
    });
  });
  c.planesMascota = gr_hogar().o.filter(o=>o.mascota && (S.planes.mascotas||[]).includes(o.v));
  return c;
}
// Una opción queda bloqueada si su nivel no corresponde al plan elegido.
// Protección Hogar y Mascotas siempre está disponible.
function bloqueada(gr, o){ if(!productoHabilitado(gr, o)) return true; const m = modActual(); if(!m || !m.niveles || gr.hogar) return false; return !m.niveles.includes(o.v); }
function motivoBloqueo(gr, o){ return !productoHabilitado(gr, o) ? 'No habilitado para su empresa' : 'No aplica en ' + (modActual()||{}).n; }
function aplica(id){ const c = cobertura(); if(id==='familia') return c.fam || c.mascota; if(id==='beneficiarios') return c.pol; return true; }
// Hay descuento de nómina en Nómina (100 % colaborador) y en Cofinanciado (la parte del colaborador).
function hayDescuento(){ return S.convenio.pago==='Nomina' || S.convenio.pago==='Cofinanciado'; }
// El titular pagador solo aplica cuando el colaborador paga el 100 % por nómina.
function pagadorAplica(){ return S.convenio.pago==='Nomina'; }
const num = v => parseInt(String(v||'').replace(/\D/g,''),10) || 0;
// Porcentaje de una parte sobre el total, con un decimal: "55,6 %".
function pct(parte, total){ if(!(total>0)) return '0 %'; const p = Math.round(parte/total*1000)/10; return p.toLocaleString('es-CO') + ' %'; }
// Valor del plan (asistencias que no son de mascotas), según quién paga.
function valorPlan(){
  const p = S.convenio.pago;
  if(p==='Cofinanciado'){ const e = num(S.convenio.valorEmpresa), col = num(S.convenio.valorColaborador); return { empresa:e, colaborador:col, total:e+col }; }
  if(p==='Nomina'){ const col = num(S.pago.valor); return { empresa:0, colaborador:col, total:col }; }
  if(p==='Empresa'){ const e = num(S.pago.valor); return { empresa:e, colaborador:0, total:e }; }
  return { empresa:0, colaborador:0, total:0 };
}
// Cada asistencia de mascota tiene su propio valor.
// Empresa paga: todo a la empresa. Nómina: todo al colaborador.
// Cofinanciado: el reparto depende de cada empresa, así que se registra por mascota.
function valorMascota(p){
  const pago = S.convenio.pago;
  if(pago==='Cofinanciado'){ const e = num(p && p.valorEmpresa), col = num(p && p.valorColaborador); return { empresa:e, colaborador:col, total:e+col }; }
  const t = num(p && p.valor);
  return pago==='Empresa' ? { empresa:t, colaborador:0, total:t } : { empresa:0, colaborador:t, total:t };
}
function valores(){
  const c = cobertura(), hayPlan = c.niveles.some(x=>!x.o.mascota);
  const pl = hayPlan ? valorPlan() : { empresa:0, colaborador:0, total:0 };
  const pets = c.mascota ? S.mascotas.map(valorMascota) : [];
  const sum = k => pets.reduce((a,x)=>a+x[k],0);
  const empresa = pl.empresa + sum('empresa'), colaborador = pl.colaborador + sum('colaborador');
  return { hayPlan, plan:pl, pets, mascotas:sum('total'), empresa, colaborador, total: pl.total + sum('total'),
           descuento: hayDescuento() ? colaborador : 0 };
}
// Persona que firma: el pagador cuando hay descuento de nómina; si no, el titular afiliado.
function firmante(){
  if(pagadorAplica() && !S.pagadorMismo) return { p:S.pagador, rol:'Titular pagador' };
  return { p:S.titular, rol:pagadorAplica() ? 'Titular afiliado y pagador' : 'Titular afiliado' };
}

/* =====================================================================
   COMPONENTES
   ===================================================================== */
function fld(bind, label, o={}){
  const id = 'f_' + bind.replace(/\./g,'_');
  const val = getP(bind) ?? '';
  const attrs = [
    o.mode ? `inputmode="${o.mode}"` : '', o.max ? `maxlength="${o.max}"` : '',
    o.ph ? `placeholder="${esc(o.ph)}"` : '', o.auto ? `autocomplete="${o.auto}"` : 'autocomplete="off"',
    o.mask ? `data-mask="${o.mask}"` : ''
  ].join(' ');
  const opt = o.opt ? ' <span class="opt">(opcional)</span>' : '';
  const input = o.area
    ? `<textarea id="${id}" data-bind="${bind}" ${attrs}>${esc(val)}</textarea>`
    : `<input type="${o.type||'text'}" id="${id}" data-bind="${bind}" value="${esc(val)}" ${attrs}>`;
  const hint = o.hintId ? `<div class="hint" id="${o.hintId}">${o.hint||''}</div>` : '';
  return `<div class="f ${o.span||''}" data-f="${bind}"><label for="${id}">${esc(label)}${opt}</label>${input}${hint}<div class="msg"></div></div>`;
}
function sel(bind, label, opciones, o={}){
  const id = 'f_' + bind.replace(/\./g,'_'); const val = getP(bind) ?? '';
  const ops = ['<option value="">Seleccione</option>'].concat(opciones.map(v=>{
    const [a,b] = Array.isArray(v) ? v : [v,v];
    return `<option value="${esc(a)}" ${a===val?'selected':''}>${esc(b)}</option>`;
  })).join('');
  return `<div class="f ${o.span||''}" data-f="${bind}"><label for="${id}">${esc(label)}</label><select id="${id}" data-bind="${bind}">${ops}</select><div class="msg"></div></div>`;
}
function seg(bind, label, opciones, o={}){
  const val = getP(bind);
  const b = opciones.map(([v,t])=>`<button type="button" data-seg="${bind}" data-v="${v}" aria-pressed="${v===val}">${esc(t)}</button>`).join('');
  return `<div class="f ${o.span||''}" data-f="${bind}"><span class="lab">${esc(label)}</span><div class="seg ${o.vertical?'v':''}" role="group" aria-label="${esc(label)}">${b}</div><div class="msg"></div></div>`;
}
const TIPOS = [['CC','CC'],['CE','CE'],['TI','TI'],['RC','RC']];
function personaCampos(base, conParentesco){
  return `<div class="grid">
    ${conParentesco ? sel(base+'.parentesco','Parentesco con el titular',PARENTESCOS,{span:'s4'}) : ''}
    ${fld(base+'.nombres','Nombres',{span:'s4'})}
    ${fld(base+'.apellidos','Apellidos',{span:'s4'})}
    ${sel(base+'.tipodoc','Tipo de documento',TIPOS,{span:'s3'})}
    ${fld(base+'.numdoc','Número de documento',{span:'s5',max:15,mode:'numeric'})}
    ${fld(base+'.fnac','Fecha de nacimiento',{span:'s4',mask:'fecha',mode:'numeric',ph:'dd/mm/aaaa',max:10})}
    ${seg(base+'.genero','Género',[['M','M'],['F','F']],{span:'s4'})}
  </div>`;
}

/* =====================================================================
   PASOS
   ===================================================================== */
const R = {};
R.convenio = () => {
  const e = empresaActual(), perm = pagosPermitidos(), reglas = SESION.reglas;
  return `
  <div class="step-h"><h2>Datos del convenio</h2><p>Se conservan para las siguientes inscripciones que haga durante la sesión.</p></div>
  <div id="vnotice"></div>
  ${SESION.empresa ? '' : `<div class="grid" style="margin-bottom:16px"><div class="f s8" data-f="convenio.empresa_id"><label for="selEmpresaConv">Empresa del convenio</label>
      <select id="selEmpresaConv"><option value="">Seleccione la empresa</option>${(SESION.empresas||[]).map(x=>`<option value="${x.id}" ${x.id===S.convenio.empresa_id?'selected':''}>${esc(x.nombre)} (NIT ${esc(x.nit)})</option>`).join('')}</select><div class="msg"></div></div></div>`}
  ${e ? `<dl class="sum" style="margin-bottom:18px">
    <div class="sum-row"><dt>Empresa</dt><dd><strong>${esc(e.nombre)}</strong></dd></div>
    <div class="sum-row"><dt>NIT</dt><dd>${esc(e.nit)}</dd></div>
    <div class="sum-row"><dt>Modelo</dt><dd>${esc(reglas.modelos[e.modelo].n)}${e.modelo===2 ? ` <span class="pctag">${reglas.descuento_modelo_2} % de descuento</span>` : ''}</dd></div>
  </dl>` : ''}
  <div class="grid">
    ${fld('convenio.asesor','Nombre de quien diligencia (asesor)',{span:'s8',auto:'name'})}
    ${!e || e.modelo !== 3 ? '' : seg('convenio.modelo_aplicado','Modelo de pago para esta inscripción',[[1,'Modelo 1 · El colaborador paga por nómina'],[2,'Modelo 2 · La empresa paga o cofinancia']],{vertical:true, span:'s8'})}
    ${!e || !perm.length ? '' : perm.length>1 ? seg('convenio.pago','¿Quién paga los planes en este convenio?',perm.map(k=>[k,PAGO[k]]),{vertical:true})
      : `<div class="f"><span class="lab">Forma de pago</span><div class="ro">${esc(PAGO[perm[0]])}<small>Definida por el modelo ${e.modelo === 3 ? S.convenio.modelo_aplicado : e.modelo}</small></div></div>`}
  </div>
  ${S.convenio.pago==='Cofinanciado' ? `<div class="block" style="margin-top:18px"><h3>Cofinanciación</h3>
    <p>Reparto del valor mensual del plan entre la empresa y el colaborador.</p>
    <div class="grid">
      ${(()=>{ const vp = valorPlan(); return `
      ${fld('convenio.valorEmpresa','Valor que cofinancia la empresa ($)',{span:'s4',mode:'numeric',max:9,hintId:'pctEmpresa',hint:'Empresa: '+pct(vp.empresa,vp.total)})}
      ${fld('convenio.valorColaborador','Valor que paga el colaborador ($)',{span:'s4',mode:'numeric',max:9,hintId:'pctColaborador',hint:'Colaborador: '+pct(vp.colaborador,vp.total)})}
      <div class="f s4"><span class="lab">Valor total del plan</span><div class="total ok" id="totalConvenio">${esc(pesos(vp.total) || '$0')}</div><div class="hint">100 %</div></div>`; })()}
    </div></div>` : ''}`;
};

R.plan = () => {
  const m = modActual(), c = cobertura();
  const reglaTxt = !m ? 'Elija primero la modalidad.'
    : m.v==='Tradicional' ? `Marque exactamente 2 asistencias. Lleva ${c.n}.`
    : m.v==='Individual' ? `Marque las asistencias que quiera. Lleva ${c.n}.`
    : `Marque 3 asistencias o más. Lleva ${c.n}.`;
  const okRegla = m && c.n >= m.min && c.n <= m.max;
  return `
  <div class="step-h"><h2>Elija el plan</h2><p>Primero la modalidad, después las asistencias. El resumen de cobertura se actualiza con lo que elige.</p></div>
  <div id="vnotice"></div>
  <div class="block"><h3>1. Modalidad de contratación</h3>
    <div class="mods">
      ${MODALIDADES.map(x=>`<button type="button" class="mod" data-mod="${x.v}" aria-pressed="${S.modalidad===x.v}">
        <span class="dot"></span><b>${x.n}</b><small>${x.d}</small><small>${x.cubre}</small></button>`).join('')}
    </div>
  </div>
  <div class="block"><h3>2. Asistencias</h3>
    <span class="total ${okRegla?'ok':(m?'bad':'')}">${esc(reglaTxt)}</span>
    ${m ? '' : '<div class="notice info">Elija una modalidad arriba para habilitar las asistencias.</div>'}
    ${m && m.niveles ? `<div class="notice info">El ${esc(m.n)} admite ${esc(m.niveles.length>1?'los niveles Premium y Premium + adicionales':'el nivel '+(m.niveles[0]==='Basico'?'Básico':m.niveles[0]))}. Protección Hogar y Mascotas siempre está disponible.</div>` : ''}
    <div class="${m?'':'lock'}">
    ${CATALOGO.map(gr => {
      const opcion = o => { const off = bloqueada(gr, o);
        const on = o.mascota ? (S.planes.mascotas||[]).includes(o.v) : S.planes[gr.g]===o.v;
        return `<button type="button" class="po ${off?'off':''}" role="checkbox" data-plan="${gr.g}" data-v="${o.v}" ${o.mascota?'data-multi="1"':''} aria-checked="${on}" ${off?'disabled':''}>
          <span class="dot"></span>
          <span><b>${o.n}</b>${o.d ? `<span class="pol">${o.d}</span>` : ''}${off?`<small>${esc(motivoBloqueo(gr,o))}</small>`:''}</span>
          <span class="cov">${o.cubre}</span></button>`; };
      const hay = S.planes[gr.g] || (gr.hogar && (S.planes.mascotas||[]).length);
      const cab = `<div class="pgroup-h"><h3>${gr.t}</h3>${hay ? `<button type="button" class="clear" data-act="clear" data-g="${gr.g}">Quitar selección</button>` : ''}</div>`;
      if(!gr.hogar) return `<div class="pgroup" data-f="planes.${gr.g}">${cab}<div class="opts" role="group" aria-label="${gr.t}">${gr.o.map(opcion).join('')}</div></div>`;
      return `<div class="pgroup" data-f="planes.${gr.g}">${cab}
        <p class="sub">Vivienda: elija una opción.</p>
        <div class="opts" role="group" aria-label="Vivienda">${gr.o.filter(o=>!o.mascota).map(opcion).join('')}</div>
        <p class="sub" style="margin-top:12px">Mascotas: puede elegir una o las dos. Cada mascota es una asistencia, con su propio valor.</p>
        <div class="opts" role="group" aria-label="Mascotas">${gr.o.filter(o=>o.mascota).map(opcion).join('')}</div>
      </div>`; }).join('')}
    </div>
  </div>`;
};

