document.addEventListener('input', e => {
  const el = e.target, b = el.dataset.bind; if(!b) return;
  if(el.dataset.mask==='fecha'){ const v = maskFecha(el.value); if(v!==el.value) el.value = v; }
  if(b==='pago.valor' || /^mascotas\.\d+\.valor(Empresa|Colaborador)?$/.test(b)){ el.value = el.value.replace(/\D/g,''); }
  setP(b, el.value);
  const bx = el.closest('.err'); if(bx){ bx.classList.remove('err'); const m = bx.querySelector('.msg'); if(m) m.textContent=''; }
  if(b==='convenio.valorEmpresa' || b==='convenio.valorColaborador'){ el.value = el.value.replace(/\D/g,''); setP(b, el.value);
    const vp = valorPlan(), tt=$('#totalConvenio'), pe=$('#pctEmpresa'), pc=$('#pctColaborador');
    if(tt) tt.textContent = pesos(vp.total) || '$0';
    if(pe) pe.textContent = 'Empresa: ' + pct(vp.empresa, vp.total);
    if(pc) pc.textContent = 'Colaborador: ' + pct(vp.colaborador, vp.total); }
  if(b==='pago.valor' || /^mascotas\.\d+\.valor(Empresa|Colaborador)?$/.test(b)){
    const v = valores(), a=$('#totalPago'), d=$('#totalDescuento'), em=$('#totalEmpresa');
    if(a) a.textContent = pesos(v.total) || '$0'; const ad = $('#autDescValor'); if(ad) ad.textContent = pesos(v.descuento) || '$0'; if(d) d.textContent = pesos(v.descuento) || '$0'; if(em) em.textContent = pesos(v.empresa) || '$0';
    const mv = /^mascotas\.(\d+)\./.exec(b);
    if(mv){ const vm = valorMascota(S.mascotas[+mv[1]]), tm = $('#totalMascota'+mv[1]), me = $('#pctME'+mv[1]), mc = $('#pctMC'+mv[1]);
      if(tm) tm.textContent = pesos(vm.total) || '$0';
      if(me) me.textContent = 'Empresa: ' + pct(vm.empresa, vm.total);
      if(mc) mc.textContent = 'Colaborador: ' + pct(vm.colaborador, vm.total); }
    const tpe = $('#pctTotEmpresa'); if(tpe) tpe.textContent = pct(v.empresa, v.total);
    const tpc = $('#pctTotDescuento'); if(tpc) tpc.textContent = pct(v.descuento, v.total); }
  const mm = /^mascotas\.(\d+)\.fnac$/.exec(b);
  if(mm){ const el2=$('#edadMascota'+mm[1]); if(el2){ const e=edadMascotaTxt(S.mascotas[+mm[1]]); el2.textContent = e || 'Escriba la fecha de nacimiento'; el2.className='total '+(e?'ok':''); } }
  if(/^beneficiarios\.\d+\.pct$/.test(b)){ const tot = S.beneficiarios.reduce((a,x)=>a+(parseInt(x.pct,10)||0),0), tt=$('#total'); if(tt){ tt.textContent=`Total asignado: ${tot} % de 100 %`; tt.className='total '+(tot===100?'ok':'bad'); } }
  siguiente._ok = null; pintarCobertura();
});
document.addEventListener('change', e => {
  const el = e.target;
  if(el.tagName==='SELECT' && el.dataset.bind){ setP(el.dataset.bind, el.value); el.closest('.err') && el.closest('.err').classList.remove('err'); siguiente._ok=null; }
  if(el.dataset.check){
    setP(el.dataset.check, el.checked);
    const ch = el.closest('.chk'); if(ch) ch.classList.remove('err');
    if(el.dataset.check==='pagadorMismo'){ const y = window.scrollY; render(); window.scrollTo(0,y); }
  }
});
document.addEventListener('click', e => {
  const el = e.target.closest('button'); if(!el) return;
  const y = window.scrollY;
  if(el.dataset.mod){
    S.modalidad = S.modalidad===el.dataset.mod ? '' : el.dataset.mod;
    siguiente._ok = null; render(); window.scrollTo(0,y); return;
  }
  if(el.dataset.plan){
    const g = el.dataset.plan, v = el.dataset.v;
    if(el.dataset.multi){
      const a = S.planes.mascotas = S.planes.mascotas || [];
      const i = a.indexOf(v); if(i>=0) a.splice(i,1); else a.push(v);
      // Mascotas que tenían un plan que se quitó quedan sin plan hasta que se elija otro.
      S.mascotas.forEach(p=>{ if(p.plan && !a.includes(p.plan)) p.plan = a.length===1 ? a[0] : ''; });
      if(a.length && !S.mascotas.length) S.mascotas.push({ plan: a.length===1 ? a[0] : '' });
    } else S.planes[g] = S.planes[g]===v ? null : v;
    siguiente._ok = null; render(); window.scrollTo(0,y); return;
  }
  if(el.dataset.seg){
    setP(el.dataset.seg, el.dataset.seg==='convenio.modelo_aplicado' ? Number(el.dataset.v) : el.dataset.v); siguiente._ok = null;
    if(el.dataset.seg==='convenio.modelo_aplicado'){ const p = pagosPermitidos(); if(!p.includes(S.convenio.pago)) S.convenio.pago = p.length===1 ? p[0] : ''; }
    if(el.dataset.seg==='firmaModo' || el.dataset.seg==='convenio.pago' || el.dataset.seg==='convenio.modelo_aplicado'){ render(); window.scrollTo(0,y); return; }
    el.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed', x===el));
    const bx = el.closest('.err'); if(bx) bx.classList.remove('err');
    pintarCobertura(); return;
  }
  if(el.dataset.go){ siguiente._ok = null; ir(+el.dataset.go); return; }
  const act = el.dataset.act; if(!act) return;
  if(act==='clear'){ S.planes[el.dataset.g] = null; if(CATALOGO.find(g=>g.g===el.dataset.g).hogar) S.planes.mascotas = []; render(); window.scrollTo(0,y); }
  if(act==='copiareparto'){ const p0 = S.mascotas[0]||{}; S.mascotas.forEach(p=>{ p.valorEmpresa = p0.valorEmpresa; p.valorColaborador = p0.valorColaborador; });
    render(); window.scrollTo(0,y); return; }
  if(act==='addben'){ S.beneficiarios.push({ origen:el.dataset.origen, pct:'' }); render(); window.scrollTo(0,y); return; }
  if(act==='add'){ const l = el.dataset.list; if(l==='conyuge') S.conyuge = {};
    else if(l==='mascotas'){ const pm = S.planes.mascotas||[]; S.mascotas.push({ plan: pm.length===1 ? pm[0] : '' }); }
    else S[l].push({}); render(); window.scrollTo(0,y); }
  if(act==='rm'){ const l = el.dataset.list; if(l==='conyuge') S.conyuge = null; else S[l].splice(+el.dataset.i,1); render(); window.scrollTo(0,y); }
  if(act==='clearpad'){ S.firma = null; S.firmaRaw = null; render(); window.scrollTo(0,y); }
  if(act==='redownload' && generado) descargar(generado.bytes, generado.nombre, 'application/pdf');
  if(act==='nueva') nuevaInscripcion();
  if(act==='reenviar') enviarInscripcion();
});
