async function iniciar(){
  try{
    const r = await fetch('/api/sesion');
    if(r.status===401){ location.replace('/login?next=' + encodeURIComponent(location.pathname + location.search)); return; }
    const d = await r.json(); if(!r.ok) throw new Error(d.error || 'No se pudo cargar la sesión.');
    SESION = d;
  } catch(e){ $('#step').innerHTML = `<div class="notice bad">${esc(e.message)}</div>`; return; }
  const interno = !['empresa_admin','empresa_usuario'].includes(SESION.usuario.rol);
  $('#lnkPanel').href = interno ? '/admin' : '/portal';
  $('#lnkPanel').textContent = interno ? 'Administración' : 'Mi panel';
  $('#empresaSesion').textContent = SESION.empresa ? SESION.empresa.nombre : SESION.usuario.nombre;
  $('#btnSalir').addEventListener('click', async () => { await fetch('/api/sesion', { method:'DELETE' }); location.href = '/login'; });
  const q = new URLSearchParams(location.search);
  aplicarEmpresa(SESION.empresa ? SESION.empresa.id : (+q.get('empresa_id') || null));
  if(!S.convenio.asesor) S.convenio.asesor = SESION.usuario.nombre;
  render();
  document.dispatchEvent(new CustomEvent('sesion-lista'));
}
iniciar();

